LOCK TABLES `products` WRITE;
/*!40000 ALTER TABLE `products` DISABLE KEYS */;
INSERT INTO `products` VALUES (1,1,'Premium Bhavnagri Bhakharvadi | Crunchy Gujarati Snack 250g','premium-bhavnagri-bhakharvadi','Indulge in the authentic taste of Gujarat with our Premium Bhavnagri Bhakharvadi. These perfectly spiced, crispy spiral rolls are handcrafted using traditional recipes passed down through generations. Made with the finest besan (gram flour), aromatic spices, and a secret blend of sesame and dry fruits, each bite delivers an irresistible crunch and a burst of tangy-spicy flavour. Ideal for tea-time snacking, festive celebrations, or gifting. No artificial preservatives. Vacuum-sealed freshness guaranteed. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1UX1vQMgwkEDk-6iIuadnlY8f1tLOV5_o',0,1,'2026-05-23 21:27:52','2026-05-23 21:27:52','Bhavnagri Foods',0,4.8,120),(2,1,'Premium Bhavnagri Chakri | Crispy Rice Flour Spirals 250g','premium-bhavnagri-chakri','Savour the classic taste of Gujarat with our Premium Bhavnagri Chakri. These golden, crispy spiral discs are made from a fine blend of rice flour and aromatic spices, expertly shaped and deep-fried to perfection. Each Chakri offers a satisfying crunch with a delicate balance of salt and spice. A beloved Gujarati snack enjoyed across generations â€“ perfect for evening chai, festive platters, and family gatherings. No artificial colours or flavours. Freshly packed for maximum crunch. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1xjf-rzKlQgHlD_Qfo9UkBqlJ_X7TLC_r',0,1,'2026-05-23 21:27:53','2026-05-23 21:27:53','Bhavnagri Foods',0,4.8,120),(3,1,'Premium Bhavnagri Chana Bhajiya | Spicy Gram Flour Fritters 250g','premium-bhavnagri-chana-bhajiya','Experience the bold, spicy crunch of our Premium Bhavnagri Chana Bhajiya. Made from select whole chana dal coated in a seasoned gram flour batter and fried to a golden crisp, these savoury fritters are bursting with authentic Gujarati flavour. Every piece is perfectly seasoned with a blend of red chilli, turmeric, and cumin for a taste that keeps you reaching for more. Ideal as a standalone snack, chai companion, or party appetiser. No MSG. No artificial preservatives. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1td1u4FG4-WQxvOmhDwidxiR_JZTRCPKm',0,1,'2026-05-23 21:27:54','2026-05-23 21:27:54','Bhavnagri Foods',0,4.8,120),(4,1,'Premium Bhavnagri Cheese Peanuts | Cheesy Coated Roasted Peanuts 250g','premium-bhavnagri-cheese-peanuts','Treat yourself to the irresistible fusion of crunchy roasted peanuts and rich, tangy cheese flavour with our Premium Bhavnagri Cheese Peanuts. Each peanut is carefully roasted and generously coated with a premium cheese seasoning that delivers a perfect balance of savoury and creamy notes. A modern twist on the classic Indian peanut snack â€“ perfect for movie nights, road trips, parties, or anytime snacking. Protein-rich and utterly addictive. No trans fats. No artificial preservatives. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1YfJz97a4v3rzYbN1LgAVloUPjlGLNtLd',0,1,'2026-05-23 21:27:55','2026-05-23 21:27:55','Bhavnagri Foods',0,4.8,120),(5,1,'Premium Bhavnagri Dry Kachori | Crispy Stuffed Mini Kachori 250g','premium-bhavnagri-dry-kachori','Discover the authentic flavour of Rajasthani-Gujarati cuisine with our Premium Bhavnagri Dry Kachori. These perfectly round, crispy mini kachoris are stuffed with a flavourful blend of moong dal, aromatic spices, and a hint of asafoetida, then deep-fried to golden perfection. Each bite reveals a delightful crunch on the outside and a rich, spiced filling inside. A timeless Indian snack perfect for tea time, travel, or festive occasions. No artificial colours. Sealed for freshness. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1TleB2POv1P3w1No6JJwVjrs1mlsiB8N4',0,1,'2026-05-23 21:27:56','2026-05-23 21:27:56','Bhavnagri Foods',0,4.8,120),(6,1,'Premium Bhavnagri Fried Moong | Crunchy Salted Moong Dal 250g','premium-bhavnagri-fried-moong','Enjoy the simple yet addictive crunch of our Premium Bhavnagri Fried Moong. Whole moong dal is carefully selected, soaked, and deep-fried to achieve the perfect golden crunch, then lightly seasoned with rock salt and a touch of turmeric. This protein-packed, guilt-free snack is a Gujarati household staple â€“ perfect for munching on the go, adding crunch to your chaats, or pairing with your evening tea. Naturally gluten-free. No artificial additives. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1T_BOviHVoUYvFFAVXRiH5mI-p23UkUyX',0,1,'2026-05-23 21:27:57','2026-05-23 21:27:57','Bhavnagri Foods',0,4.8,120),(7,1,'Premium Bhavnagri Garlic Chana Bhajiya | Lahsun Spiced Fritters 250g','premium-bhavnagri-garlic-chana-bhajiya','Elevate your snack game with our Premium Bhavnagri Garlic Chana Bhajiya â€“ a bold, flavourful twist on the classic Gujarati bhajiya. Whole chana dal is infused with freshly crushed garlic, coated in a seasoned gram flour batter, and fried to a perfect golden crunch. The robust garlic aroma combined with the heat of red chilli and the earthiness of cumin creates an unforgettable taste experience. Perfect for garlic lovers who crave bold flavours with their chai. No MSG. No artificial flavours. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1td1u4FG4-WQxvOmhDwidxiR_JZTRCPKm',0,1,'2026-05-23 21:27:58','2026-05-23 21:27:58','Bhavnagri Foods',0,4.8,120),(8,1,'Premium Bhavnagri Hing Jeera Chana | Asafoetida Cumin Roasted Chana 250g','premium-bhavnagri-hing-jeera-chana','Relish the aromatic duo of hing (asafoetida) and jeera (cumin) with our Premium Bhavnagri Hing Jeera Chana. Select whole roasted chana is tossed with pure hing, roasted cumin powder, black salt, and a hint of amchur (dry mango powder) for a flavour profile that is tangy, earthy, and deeply satisfying. This traditional Indian snack is rich in protein and fibre â€“ a wholesome alternative to fried snacks. Perfect for health-conscious snackers and flavour enthusiasts alike. No artificial colours or preservatives. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1B_tKfcZdWlDCZ_dM_j-QcXXM8lyqprVD',0,1,'2026-05-23 21:27:59','2026-05-23 21:27:59','Bhavnagri Foods',0,4.8,120),(9,1,'Premium Bhavnagri Lasaniya Gathiya | Garlic Flavoured Gram Flour Noodles 250g','premium-bhavnagri-lasaniya-gathiya','Experience the irresistible garlic punch of our Premium Bhavnagri Lasaniya Gathiya. These thick, crunchy gram flour noodles are kneaded with fresh garlic paste and a robust spice blend, then pressed through traditional moulds and deep-fried to golden perfection. The bold lasaniya (garlic) flavour sets these apart from regular gathiya â€“ every strand is packed with aromatic garlic goodness. A must-have for garlic lovers and a staple in every Gujarati household. No artificial flavours. Freshly made and sealed. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1wwHh0K3kRuLpLUYNJbU80Ktq_s6zNY5U',0,1,'2026-05-23 21:28:00','2026-05-23 21:28:00','Bhavnagri Foods',0,4.8,120),(10,1,'Premium Bhavnagri Makai Chevdo | Crispy Corn Flakes Mix 250g','premium-bhavnagri-makai-chevdo','Delight in the sweet-savoury-spicy symphony of our Premium Bhavnagri Makai Chevdo. This signature Gujarati mix combines crispy corn flakes (makai) with roasted peanuts, crunchy sev, curry leaves, mustard seeds, and a perfectly balanced seasoning of sugar, salt, and chilli. Every handful is a burst of contrasting textures and flavours â€“ the hallmark of authentic Gujarati chevdo. A festive favourite and everyday indulgence. No artificial preservatives. Packed fresh in food-grade pouches. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1-ZS_THocS6tg_C-pKsduvnmvnrCe-DZ-',0,1,'2026-05-23 21:28:01','2026-05-23 21:28:01','Bhavnagri Foods',0,4.8,120),(11,1,'Premium Bhavnagri Makhaniya Gathiya | Buttery Soft Gram Flour Noodles 250g','premium-bhavnagri-makhaniya-gathiya','Melt into the buttery softness of our Premium Bhavnagri Makhaniya Gathiya. Unlike regular gathiya, these are crafted with a special dough enriched with extra oil and butter flavouring, giving them a distinctively smooth, melt-in-the-mouth texture. Lightly spiced with black pepper and ajwain (carom seeds), each strand offers a delicate crunch that dissolves into rich, buttery flavour. The softest gathiya in our range â€“ ideal for those who prefer mild, comforting snacks. No artificial colours. Freshly prepared. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/17YcrtIoQSdbGsGHCkADCqb-9oR_g0MrN',0,1,'2026-05-23 21:28:02','2026-05-23 21:28:02','Bhavnagri Foods',0,4.8,120),(12,1,'Premium Bhavnagri Mari Gathiya | Black Pepper Spiced Gram Flour Noodles 250g','premium-bhavnagri-mari-gathiya','Ignite your taste buds with our Premium Bhavnagri Mari Gathiya. These thick, robust gram flour noodles are generously seasoned with freshly ground black pepper (mari), creating a bold, warming heat that lingers with every bite. The coarse texture and peppery kick make this the most flavourful gathiya in our collection. Crafted using time-honoured Bhavnagri techniques with pure ingredients. A favourite among spice lovers and a perfect companion to hot masala chai. No artificial spices. Freshly sealed. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/19vQ8EUEicmNF9JpNDH8mjgynNhtzv1-7',0,1,'2026-05-23 21:28:03','2026-05-23 21:28:03','Bhavnagri Foods',0,4.8,120),(13,1,'Premium Bhavnagri Nylon Gathiya | Ultra-Fine Silky Gram Flour Sev 250g','premium-bhavnagri-nylon-gathiya','Discover the legendary smoothness of our Premium Bhavnagri Nylon Gathiya â€“ the finest and thinnest gathiya you will ever taste. These ultra-fine gram flour strands are as delicate as silk threads, pressed through the finest sev moulds and fried to an airy, feather-light crispiness. Named for their nylon-like fineness, they dissolve on your tongue with a subtle spice and a satisfying crunch. Perfect as a topping for chaats, mixed with chevdo, or enjoyed on their own. A Bhavnagri speciality. No preservatives. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1tblzxpC_GtliNgyKWkC7Za5axu0hK7qw',0,1,'2026-05-23 21:28:05','2026-05-23 21:28:05','Bhavnagri Foods',0,4.8,120),(14,1,'Premium Bhavnagri Papad Chevdo | Crispy Papad Flakes Mix 250g','premium-bhavnagri-papad-chevdo','Experience the unique crunch of our Premium Bhavnagri Papad Chevdo â€“ a distinctive Gujarati snack mix built around crispy, crumbled papad pieces. Bite-sized papad flakes are combined with roasted peanuts, sesame seeds, curry leaves, and a sweet-spicy-tangy seasoning that captures the essence of Gujarati flavour. The irregular shapes and textures create a snacking experience unlike any other chevdo. A rare and authentic recipe from the kitchens of Bhavnagar. No artificial colours or preservatives. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1J1g5PZkSqIzf7EUL0-1w0-Q-eupjXO3E',0,1,'2026-05-23 21:28:06','2026-05-23 21:28:06','Bhavnagri Foods',0,4.8,120),(15,1,'Premium Bhavnagri Pizza Puri | Italian-Indian Fusion Crispy Puri 250g','premium-bhavnagri-pizza-puri','Embark on a flavour adventure with our Premium Bhavnagri Pizza Puri â€“ where Italian pizza seasoning meets the crispy Indian puri. These thin, crunchy mini puris are generously dusted with a tangy-spicy pizza-inspired seasoning blend featuring oregano, tomato powder, cheese flavour, and a hint of chilli. A modern fusion snack that appeals to all ages â€“ kids love the cheesy-tangy taste, adults appreciate the satisfying crunch. Perfect for parties, lunchboxes, and on-the-go munching. No trans fats. Vegetarian. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1uJ45zcuTcXA4LxzUhERXO4xkeRoNBbA4',0,1,'2026-05-23 21:28:07','2026-05-23 21:28:07','Bhavnagri Foods',0,4.8,120),(16,1,'Premium Bhavnagri Salted Peanuts | Classic Roasted & Salted Peanuts 250g','premium-bhavnagri-salted-peanuts','Keep it classic with our Premium Bhavnagri Salted Peanuts. Handpicked, premium-grade peanuts are slow-roasted to bring out their natural nutty richness, then perfectly seasoned with fine rock salt. Simple, satisfying, and packed with natural protein, healthy fats, and essential minerals. Whether you are snacking between meals, fuelling a workout, or adding crunch to your salads and chaats, these salted peanuts are the perfect wholesome choice. No added oil. No artificial flavours. Naturally gluten-free. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1YhVHFwgDmhKv6dq-apK3OmQqZb00ANU6',0,1,'2026-05-23 21:28:08','2026-05-23 21:28:08','Bhavnagri Foods',0,4.8,120),(17,1,'Premium Bhavnagri Special Sev | Fine Spiced Gram Flour Vermicelli 250g','premium-bhavnagri-special-sev','Savour the quintessential Gujarati snack with our Premium Bhavnagri Special Sev. These fine gram flour vermicelli strands are crafted from a premium besan dough seasoned with a proprietary spice blend, pressed through precision moulds, and fried to a uniform golden crispiness. Our \'Special\' recipe includes a secret touch of ajwain and black salt that elevates this sev above the ordinary. Essential for topping chaats, garnishing dishes, or straight-from-the-pack snacking. A kitchen staple and a snack-time star. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/14QGf0yk8NzBK0bPSgPD8U4Fvnh4Zy2IO',0,1,'2026-05-23 21:28:09','2026-05-23 21:28:09','Bhavnagri Foods',0,4.8,120),(18,1,'Premium Bhavnagri Sweet & Chatpata Peanuts | Tangy-Sweet Coated Peanuts 250g','premium-bhavnagri-sweet-chatpata-peanuts','Get hooked on the playful sweet-and-sour dance of our Premium Bhavnagri Sweet & Chatpata Peanuts. Crunchy roasted peanuts are coated with a unique sweet-tangy-spicy masala blend featuring jaggery, amchur (dry mango), chaat masala, and a kick of red chilli. The result is an explosively flavourful snack that hits every taste note â€“ sweet, sour, spicy, and salty â€“ in perfect harmony. A crowd-pleaser at every gathering and impossible to stop at just one handful. Vegetarian. No artificial sweeteners. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1tqM-0ErIrcjMlZfjsv-tayAiHRdaIiMA',0,1,'2026-05-23 21:28:10','2026-05-23 21:28:10','Bhavnagri Foods',0,4.8,120),(19,1,'Premium Bhavnagri Tikha Gathiya | Extra Spicy Gram Flour Noodles 250g','premium-bhavnagri-tikha-gathiya','Dare to take on the heat with our Premium Bhavnagri Tikha Gathiya â€“ the spiciest gathiya in our range. These thick, crunchy gram flour noodles are loaded with an extra-hot blend of red chilli, black pepper, and a proprietary \'tikha masala\' that delivers an intense, lingering heat. Not for the faint-hearted â€“ this is gathiya for true spice warriors. The aggressive spice level is balanced by the nutty richness of premium besan, making every fiery bite deeply satisfying. Made with pure spices. Freshly sealed for potency. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1Xso6RnfKDjm6jrv1hFGdi0g_4Pd2N7wC',0,1,'2026-05-23 21:28:11','2026-05-23 21:28:11','Bhavnagri Foods',0,4.8,120),(20,1,'Premium Bhavnagri Til Papdi | Sesame Crispy Wafer Snack 250g','premium-bhavnagri-til-papdi','Celebrate the timeless flavours of Gujarat with our Premium Bhavnagri Til Papdi. These paper-thin, crispy wafers are crafted from a delicate dough of gram flour enriched with generous amounts of white sesame seeds (til) and a subtle spice blend. Each papdi shatters into a delightful crunch, releasing the warm, nutty aroma of toasted sesame. A traditional Gujarati delicacy often served during festivals, weddings, and special occasions. Rich in calcium and iron from sesame seeds. No artificial additives. Freshly made. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1Qt_0yqqWQaNGWevhCZOsA1HpbfZEAbbK',0,1,'2026-05-23 21:28:11','2026-05-23 21:28:11','Bhavnagri Foods',0,4.8,120),(21,1,'Premium Bhavnagri Magic Puri | Crispy Spiced Flour Crackers 250g','premium-bhavnagri-magic-puri','Delight in the spellbinding taste of our Premium Bhavnagri Magic Puri. These circular, flaky, and crispy golden crackers are seasoned with a secret spices blend of black pepper, carom seeds, and a hint of turmeric. Expertly kneaded and rolled to perfection, each puri delivers a satisfying crunch and a rich, buttery savoriness that melts in your mouth. Perfect for tea-time, family picnics, or festive platters. No artificial colors. Freshly packed. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1OxnDabNO6L5XGh0pDP6hBPyj2WprCggX',0,1,'2026-05-23 21:28:12','2026-05-23 21:28:12','Bhavnagri Foods',0,4.8,120),(22,1,'Premium Bhavnagri Mix Kathol | Crunchy Sprouted Spiced Legumes Mix 250g','premium-bhavnagri-mix-kathol','Savor the wholesome crunch and authentic spices of our Premium Bhavnagri Mix Kathol. This traditional Gujarati namkeen is a vibrant mix of slow-roasted sprouted legumes (kathol) including green mung, moth beans, and black chick peas, tossed with golden sev, crispy peanuts, and infused with red chilli, dry mango powder, and aromatic hing. Packed with protein and dietary fibre, it is the perfect guilt-free snack for health-conscious snackers and spice lovers alike. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1nQaLTgT5VZ1Sq-7ATNmTrqcHZVTkq4up',0,1,'2026-05-23 21:28:13','2026-05-23 21:28:13','Bhavnagri Foods',0,4.8,120),(23,1,'Premium Bhavnagri Nylon Papadi | Crispy Wafer Gram Flour Ribbon Snack 250g','premium-bhavnagri-nylon-papadi','Experience the delicate, paper-thin crunch of our Premium Bhavnagri Nylon Papadi. These long, ultra-fine crispy ribbons are crafted from a seasoned gram flour (besan) dough enriched with carom seeds (ajwain) and a touch of asafoetida. Deep-fried to a light, golden airiness, each papadi melts on your tongue with a mild, comforting spice. A classic Gujarati snack typically served during Sunday breakfasts with fresh jalebis and spicy papaya sambharo. No preservatives. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1MxcY3M-cFOsggnqZ_TADQdJPIq4-WY5u',0,1,'2026-05-23 21:28:14','2026-05-23 21:28:14','Bhavnagri Foods',0,4.8,120),(24,1,'Premium Bhavnagri Jhal Muri | Spicy Tangy Puffed Rice Mix 250g','premium-bhavnagri-jhal-muri','Ignite your senses with the iconic street food flavor of our Premium Bhavnagri Jhal Muri. This classic Bengali-Gujarati fusion namkeen features light, airy puffed rice (muri) tossed with crunchy sev, roasted peanuts, dried coconut slices, and an explosive, tangy-spicy spice blend that mimics the authentic mustard oil and mango pickle infusion. Extremely light, fiery, and addictive - it is the ultimate companion for evening chats and rainy afternoons. Net Weight: 250g.',NULL,249.00,199.00,0.00,'250g',100,'https://lh3.googleusercontent.com/d/1eWkfd1cLYWiBg64KABuuEf3RSQINzwOD',0,1,'2026-05-23 21:28:15','2026-05-23 21:28:15','Bhavnagri Foods',0,4.8,120);
